cd /home/runner/chandler-wt && git fetch origin main --quiet && git show origin/main:S01/E26.md | grep -c "Source: friend" ; echo "--- filed SHAs count above; now compute unfiled ---"; python3 - <<'PY'
import subprocess
def sh(*a):
    return subprocess.run(['git','-C','/home/runner/chandler-wt']+list(a),capture_output=True,text=True).stdout
filed = set()
t = sh('show','origin/main:S01/E26.md')
for line in t.splitlines():
    if line.startswith('Source: friend/'):
        filed.add(line.split('@')[-1].strip())
unfiled=[]
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    out = sh('log','--format=%H|%cI|%s','origin/friend/'+b)
    for l in out.splitlines():
        h,ci,subj = l.split('|',2)
        body = sh('log','-1','--format=%B',h)
        if 'Friend-Message: 1' in body and 'S01/E26' in body and h not in filed:
            unfiled.append((ci,b,h,body.strip().splitlines()[-1][:90]))
for u in sorted(unfiled):
    print(u[0],u[1],u[2][:8],u[3])
print('total unfiled in E26:',len(unfiled))
PY
